export class MapNavigation {
 constructor(data){this.wallBuckets=new Map();for(const line of data.wallSegments||[]){for(let x=Math.floor(Math.min(line[0],line[2])/4);x<=Math.floor(Math.max(line[0],line[2])/4);x++)for(let z=Math.floor(Math.min(line[1],line[3])/4);z<=Math.floor(Math.max(line[1],line[3])/4);z++){const k=x+','+z;if(!this.wallBuckets.has(k))this.wallBuckets.set(k,[]);this.wallBuckets.get(k).push(line);}}this.data=data;this.areas=data.areas;this.byId=new Map(this.areas.map(a=>[a.id,a]));this.bounds=data.bounds;this.buckets=new Map();for(const a of this.areas){const b=a.bounds;for(let x=Math.floor(b[0]/4);x<=Math.floor(b[2]/4);x++)for(let z=Math.floor(b[1]/4);z<=Math.floor(b[3]/4);z++){const k=x+','+z;if(!this.buckets.has(k))this.buckets.set(k,[]);this.buckets.get(k).push(a);}}this.connectNearby();this.normalizePoints();}
 normalizePoints(){this.data.sites=this.data.sites.map(s=>this.safePoint(s));const s=this.data.sites[0];if(!s)return;const root=this.areaAt(s.x,s.z,s.floor)||this.nearest(s.x,s.z,s.floor),reachable=new Set([root.id]),queue=[root.id];for(let i=0;i<queue.length;i++)for(const id of this.byId.get(queue[i]).links)if(this.byId.has(id)&&!reachable.has(id)){reachable.add(id);queue.push(id);}for(const side of ['attack','defend'])this.data.spawns[side]=this.data.spawns[side].map(original=>{const p=this.safePoint(original),area=this.areaAt(p.x,p.z,p.floor);if(area&&reachable.has(area.id))return p;let best=Infinity,result=p;for(const id of reachable){const q=this.center(this.byId.get(id)),d=(q.x-p.x)**2+(q.z-p.z)**2+Math.abs(q.floor-p.floor)*4;if(d<best&&!this.blocked(q.x,q.z,.37,q.floor)){best=d;result={...original,...q};}}return result;});}
 height(a,x,z){const b=a.bounds,u=Math.max(0,Math.min(1,(x-b[0])/(b[2]-b[0]||1))),v=Math.max(0,Math.min(1,(z-b[1])/(b[3]-b[1]||1)));return (a.heights[0]*(1-u)+a.heights[1]*u)*(1-v)+(a.heights[2]*(1-u)+a.heights[3]*u)*v;}
 areaAt(x,z,floor=0){const near=this.buckets.get(Math.floor(x/4)+','+Math.floor(z/4))||[];let chosen=null,best=Infinity;for(const a of near){const b=a.bounds;if(x<b[0]-.05||x>b[2]+.05||z<b[1]-.05||z>b[3]+.05)continue;const d=Math.abs(this.height(a,x,z)-floor);if(d<best){best=d;chosen=a;}}return chosen;}
 nearest(x,z,floor=0){let best=Infinity,chosen;for(const a of this.areas){const b=a.bounds,d=Math.max(b[0]-x,0,x-b[2])**2+Math.max(b[1]-z,0,z-b[3])**2+Math.abs(this.height(a,x,z)-floor)*.15;if(d<best){best=d;chosen=a;}}return chosen;}
 floorAt(x,z,floor=0){let a=this.areaAt(x,z,floor);if(!a){const near=this.buckets.get(Math.floor(x/4)+','+Math.floor(z/4))||[];a=near.find(a=>{const b=a.bounds;return Math.max(b[0]-x,0,x-b[2])<.5&&Math.max(b[1]-z,0,z-b[3])<.5&&Math.abs(this.height(a,x,z)-floor)<.76;});}return a?this.height(a,x,z):null;}
 connectNearby(){const checked=new Set();for(const a of this.areas){const b=a.bounds;for(let x=Math.floor(b[0]/4)-1;x<=Math.floor(b[2]/4)+1;x++)for(let z=Math.floor(b[1]/4)-1;z<=Math.floor(b[3]/4)+1;z++)for(const c of this.buckets.get(x+','+z)||[]){if(c===a)continue;const key=[a.id,c.id].sort((x,y)=>x-y).join(',');if(checked.has(key))continue;checked.add(key);const d=c.bounds,dx=Math.max(b[0]-d[2],d[0]-b[2],0),dz=Math.max(b[1]-d[3],d[1]-b[3],0);if(dx>.65||dz>.65)continue;const px=(Math.max(b[0],d[0])+Math.min(b[2],d[2]))/2,pz=(Math.max(b[1],d[1])+Math.min(b[3],d[3]))/2,ha=this.height(a,px,pz),hc=this.height(c,px,pz);if(Math.abs(ha-hc)>.76)continue;let clear=true;for(const [ox,oz]of [[0,0],[.2,0],[-.2,0],[0,.2],[0,-.2]])for(const h of [.4,1.4])if(this.contents(px+ox,Math.max(ha,hc)+h,pz+oz)===-2||this.wallBlocked(px,pz,.25,Math.max(ha,hc)))clear=false;if(clear){if(!a.links.includes(c.id))a.links.push(c.id);if(!c.links.includes(a.id))c.links.push(a.id);}}}}
 safePoint(point){if(!this.blocked(point.x,point.z,.37,point.floor))return point;let closest=null,best=Infinity;for(const a of this.areas){const p=this.center(a),distance=(p.x-point.x)**2+(p.z-point.z)**2+Math.abs(p.floor-point.floor)*4;if(distance<best&&!this.blocked(p.x,p.z,.37,p.floor)){best=distance;closest=p;}}return closest?{...point,...closest}:point;}
 contents(x,y,z){const d=this.data;for(const root of d.roots){if(typeof root==='object'){const b=root.bounds;if(x*32<b[0]||x*32>b[3]||-z*32<b[1]||-z*32>b[4]||y*32<b[2]||y*32>b[5])continue;}let n=typeof root==='object'?root.node:root;for(let i=0;i<1000;i++){if(n<0){if(d.leaves[-n-1]===-2)return -2;break;}const [p,a,b]=d.nodes[n],[nx,ny,nz,dist]=d.planes[p];n=nx*x*32-ny*z*32+nz*y*32-dist>=0?a:b;}}return -1;}
 wallBlocked(x,z,r,floor){for(let bx=Math.floor((x-r)/4);bx<=Math.floor((x+r)/4);bx++)for(let bz=Math.floor((z-r)/4);bz<=Math.floor((z+r)/4);bz++)for(const [ax,az,bx1,bz1,lo,hi]of this.wallBuckets.get(bx+','+bz)||[]){if(hi<floor+.25||lo>floor+1.5)continue;const dx=bx1-ax,dz=bz1-az,t=Math.max(0,Math.min(1,((x-ax)*dx+(z-az)*dz)/(dx*dx+dz*dz||1)));if(Math.hypot(x-ax-dx*t,z-az-dz*t)<r)return true;}return false;}
 blocked(x,z,r=.37,floor=0){const next=this.floorAt(x,z,floor);if(next===null||Math.abs(next-floor)>.76||this.wallBlocked(x,z,r,next))return true;for(const [dx,dz]of [[0,0],[r,0],[-r,0],[0,r],[0,-r]])for(const h of [.3,1,1.55])if(this.contents(x+dx,next+h,z+dz)===-2)return true;return false;}
 center(a){const b=a.bounds,x=(b[0]+b[2])/2,z=(b[1]+b[3])/2;return{x,z,floor:this.height(a,x,z)};}
 path(sx,sz,tx,tz,floor=0,targetFloor=floor){const start=this.areaAt(sx,sz,floor)||this.nearest(sx,sz,floor),goal=this.areaAt(tx,tz,targetFloor)||this.nearest(tx,tz,targetFloor);if(!start||!goal)return[];if(start===goal)return[{x:tx,z:tz}];const queue=[start.id],from=new Map([[start.id,null]]);for(let at=0;at<queue.length;at++){const id=queue[at];if(id===goal.id){const result=[];let n=id;while(n!==start.id){result.unshift(this.center(this.byId.get(n)));n=from.get(n);}result.push({x:tx,z:tz});return result;}for(const n of this.byId.get(id).links)if(this.byId.has(n)&&!from.has(n)){from.set(n,id);queue.push(n);}}return[];}
 spawn(attacking,i=0){const list=this.data.spawns[attacking?'attack':'defend'];const s=list[i%list.length];if(!s)throw Error('地图缺少出生点');const target=attacking?this.data.sites[0]:this.data.spawns.attack[0];return this.safePoint({...s,yaw:s.yaw??Math.atan2(s.x-target.x,s.z-target.z)});}
}
